// Demonstrates retry, circuit breaker, cache fallback when a service is down.
package com.bank.gateway.demo;

import java.math.BigDecimal;
import java.util.logging.*;

public class ResilientGatewayDemo {
    private static final Logger log = Logger.getLogger("ResilientGateway");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new RgLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        BalanceService service = new BalanceService();
        BalanceGateway gateway = new BalanceGateway(service);

        log.info("=== Phase 1: service healthy ===");
        for (int i = 0; i < 2; i++) show(gateway);

        log.info("=== Phase 2: transient blip (retry recovers) ===");
        service.setMode(BalanceService.Mode.BLIP);
        show(gateway);

        log.info("=== Phase 3: sustained outage (breaker opens, cache fallback) ===");
        service.setMode(BalanceService.Mode.DOWN);
        for (int i = 0; i < 6; i++) { show(gateway); Thread.sleep(300); }

        log.info("=== Phase 4: recovered (half-open closes) ===");
        service.setMode(BalanceService.Mode.HEALTHY);
        Thread.sleep(2000);
        show(gateway);
    }

    private static void show(BalanceGateway g) {
        BigDecimal bal = g.getBalance("SAV2001");
        log.info(() -> "Rajesh balance served = Rs." + bal);
    }
}

// ─── Would be in client/BalanceService.java ───
class BalanceService {
    enum Mode { HEALTHY, BLIP, DOWN }
    private Mode mode = Mode.HEALTHY;
    private int blipCounter = 0;
    void setMode(Mode m) { this.mode = m; this.blipCounter = 0; }

    BigDecimal getBalance(String accountId) {
        switch (mode) {
            case DOWN:
                throw new RuntimeException("BalanceService DOWN");
            case BLIP:
                blipCounter++;
                if (blipCounter < 2) throw new RuntimeException("BalanceService transient blip");
                return new BigDecimal("1000000.00");
            default:
                return new BigDecimal("1000000.00");
        }
    }
}

// ─── Would be in resilience/BalanceCache.java ───
class BalanceCache {
    private final java.util.Map<String, BigDecimal> cache = new java.util.HashMap<>();
    void put(String id, BigDecimal v) { cache.put(id, v); }
    BigDecimal get(String id) { return cache.getOrDefault(id, BigDecimal.ZERO); }
}

// ─── Would be in resilience/CircuitBreaker.java ───
class CircuitBreaker {
    private static final Logger log = Logger.getLogger("ResilientGateway");
    enum State { CLOSED, OPEN, HALF_OPEN }
    private State state = State.CLOSED;
    private int failures = 0;
    private final int threshold;
    private long openedAt = 0;
    private final long coolDownMs;

    CircuitBreaker(int threshold, long coolDownMs) { this.threshold = threshold; this.coolDownMs = coolDownMs; }

    boolean allowRequest() {
        if (state == State.OPEN) {
            if (System.currentTimeMillis() - openedAt >= coolDownMs) {
                state = State.HALF_OPEN;
                log.warning("Circuit HALF_OPEN — trial call allowed");
                return true;
            }
            return false; // fail fast
        }
        return true;
    }

    void recordSuccess() {
        if (state == State.HALF_OPEN) log.info("Circuit CLOSED — service recovered");
        state = State.CLOSED; failures = 0;
    }

    void recordFailure() {
        failures++;
        if (failures >= threshold || state == State.HALF_OPEN) {
            state = State.OPEN; openedAt = System.currentTimeMillis();
            log.severe(() -> "Circuit OPEN after " + failures + " failures");
        }
    }

    State getState() { return state; }
}

// ─── Would be in core/BalanceGateway.java ───
class BalanceGateway {
    private static final Logger log = Logger.getLogger("ResilientGateway");
    private final BalanceService service;
    private final CircuitBreaker breaker = new CircuitBreaker(3, 1500);
    private final BalanceCache cache = new BalanceCache();

    BalanceGateway(BalanceService service) { this.service = service; }

    BigDecimal getBalance(String accountId) {
        // 1) Circuit breaker: fail fast if open.
        if (!breaker.allowRequest()) {
            log.warning("Breaker OPEN — serving cached fallback without calling service");
            return cache.get(accountId);
        }
        // 2) Bounded retry with backoff for transient blips.
        int attempts = 3; long wait = 100;
        for (int i = 1; i <= attempts; i++) {
            try {
                BigDecimal bal = service.getBalance(accountId);
                breaker.recordSuccess();
                cache.put(accountId, bal); // refresh cache on success
                return bal;
            } catch (RuntimeException ex) {
                log.warning("Attempt " + i + " failed: " + ex.getMessage());
                if (i == attempts) {
                    breaker.recordFailure();
                    log.severe("All retries failed — serving cached fallback");
                    return cache.get(accountId); // 3) fallback
                }
                sleep(wait); wait *= 2; // exponential backoff
            }
        }
        return cache.get(accountId);
    }

    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
}

// ─── Would be in RgLogFormatter.java ───
class RgLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
