package com.bank.gateway.demo;

import java.util.logging.*;

public class DynamicRoutingDemo {
    private static final Logger log = Logger.getLogger("DynamicRouting");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new DrLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RouteDefinitionRepository repo = new RouteDefinitionRepository();
        DynamicRouteEngine engine = new DynamicRouteEngine(repo);

        // Start: all payments to the OLD backend.
        repo.save(new RouteDefinition("payment-old", "/api/v1/payments", "payment-service-old", 100));
        repo.save(new RouteDefinition("account", "/api/v1/accounts", "account-service", 100));
        engine.refresh();

        log.info("=== Phase 1: all payments → OLD ===");
        for (int i = 0; i < 4; i++) route(engine, "/api/v1/payments/pay");

        // Runtime change: canary 25% of payments to the NEW backend.
        log.info("=== Phase 2: add weighted route, 25% payments → NEW ===");
        repo.save(new RouteDefinition("payment-old", "/api/v1/payments", "payment-service-old", 75));
        repo.save(new RouteDefinition("payment-new", "/api/v1/payments", "payment-service-new", 25));
        engine.refresh();
        for (int i = 0; i < 4; i++) route(engine, "/api/v1/payments/pay");

        // Runtime reroute: account service to a standby.
        log.info("=== Phase 3: reroute account → standby ===");
        repo.save(new RouteDefinition("account", "/api/v1/accounts", "account-service-standby", 100));
        engine.refresh();
        route(engine, "/api/v1/accounts/SAV2001");
    }

    private static void route(DynamicRouteEngine engine, String path) {
        String backend = engine.match(path);
        log.info(() -> path + " → " + backend);
    }
}

// ─── Would be in route/RouteDefinition.java ───
class RouteDefinition {
    private final String id; private final String pathPrefix;
    private final String backend; private final int weight;
    RouteDefinition(String id, String pathPrefix, String backend, int weight) {
        this.id = id; this.pathPrefix = pathPrefix; this.backend = backend; this.weight = weight;
    }
    String getId() { return id; }
    String getPathPrefix() { return pathPrefix; }
    String getBackend() { return backend; }
    int getWeight() { return weight; }
}

// ─── Would be in route/RouteDefinitionRepository.java ───
class RouteDefinitionRepository {
    // keyed by id so save() both adds and updates (like InMemoryRouteDefinitionRepository)
    private final java.util.Map<String, RouteDefinition> defs = new java.util.LinkedHashMap<>();
    void save(RouteDefinition d) { defs.put(d.getId(), d); }
    void delete(String id) { defs.remove(id); }
    java.util.Collection<RouteDefinition> findAll() { return new java.util.ArrayList<>(defs.values()); }
}

// ─── Would be in route/DynamicRouteEngine.java ───
class DynamicRouteEngine {
    private static final Logger log = Logger.getLogger("DynamicRouting");
    private final RouteDefinitionRepository repo;
    private volatile java.util.List<RouteDefinition> compiled = java.util.List.of(); // cached route table
    private final java.util.Random rnd = new java.util.Random(42);

    DynamicRouteEngine(RouteDefinitionRepository repo) { this.repo = repo; }

    // Equivalent to publishing a RefreshRoutesEvent: rebuild the cached table.
    void refresh() {
        compiled = new java.util.ArrayList<>(repo.findAll());
        log.info(() -> "Routes refreshed: " + compiled.size() + " definitions");
    }

    // Match a path to a backend; apply weighted selection when multiple routes share a prefix.
    String match(String path) {
        java.util.List<RouteDefinition> candidates = new java.util.ArrayList<>();
        for (RouteDefinition d : compiled) if (path.startsWith(d.getPathPrefix())) candidates.add(d);
        if (candidates.isEmpty()) return "404-no-route";
        if (candidates.size() == 1) return candidates.get(0).getBackend();
        return weightedPick(candidates); // canary / blue-green split
    }

    private String weightedPick(java.util.List<RouteDefinition> candidates) {
        int total = candidates.stream().mapToInt(RouteDefinition::getWeight).sum();
        int roll = rnd.nextInt(total);
        int acc = 0;
        for (RouteDefinition d : candidates) {
            acc += d.getWeight();
            if (roll < acc) return d.getBackend();
        }
        return candidates.get(0).getBackend();
    }
}

