package com.bank.gateway.demo;

import java.util.concurrent.*;
import java.util.logging.*;

public class OverheadDemo {
    private static final Logger log = Logger.getLogger("Overhead");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new OvLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        OptimizedGateway gateway = new OptimizedGateway();
        int requests = 200;

        log.info("=== Steady traffic: connection reuse + hybrid rate limit + async log ===");
        for (int i = 0; i < requests; i++) gateway.handle("SAV2001");

        log.info("=== Burst: 50 identical in-flight lookups → coalesced to 1 call ===");
        ExecutorService pool = Executors.newFixedThreadPool(16);
        CountDownLatch latch = new CountDownLatch(50);
        for (int i = 0; i < 50; i++) pool.submit(() -> { gateway.coalescedLookup("HOT-ACCOUNT"); latch.countDown(); });
        latch.await();
        pool.shutdown();

        gateway.report();
    }
}

// ─── Would be in perf/ConnectionPool.java ───
class ConnectionPool {
    private int open = 0; private int reuses = 0; private int newHandshakes = 0;
    private final int maxConnections;
    ConnectionPool(int maxConnections) { this.maxConnections = maxConnections; }
    // Reuse an existing connection when available; only handshake when pool must grow.
    void acquire() {
        if (open > 0 && open <= maxConnections) { reuses++; }      // HTTP/2 multiplex / keep-alive reuse
        else { newHandshakes++; open = Math.min(open + 1, maxConnections); } // TCP+TLS handshake
    }
    double reusePercent() {
        int total = reuses + newHandshakes;
        return total == 0 ? 0 : (reuses * 100.0 / total);
    }
    int getNewHandshakes() { return newHandshakes; }
}

// ─── Would be in perf/HybridRateLimiter.java ───
class HybridRateLimiter {
    private int localTokens; private final int capacity;
    private int redisSyncs = 0; private long lastSync = 0; private final long syncIntervalMs;
    HybridRateLimiter(int capacity, long syncIntervalMs) {
        this.capacity = capacity; this.localTokens = capacity; this.syncIntervalMs = syncIntervalMs;
    }
    // Check local bucket instantly (no network); sync to Redis only every ~100ms.
    boolean allow() {
        long now = System.currentTimeMillis();
        if (now - lastSync >= syncIntervalMs) { syncToRedis(); lastSync = now; }
        if (localTokens > 0) { localTokens--; return true; }
        return true; // demo: allow; real impl would refill from Redis sync
    }
    private void syncToRedis() { redisSyncs++; localTokens = capacity; } // periodic, not per request
    int getRedisSyncs() { return redisSyncs; }
}

// ─── Would be in perf/AsyncBatchLogger.java ───
class AsyncBatchLogger {
    private static final Logger log = Logger.getLogger("Overhead");
    private final BlockingQueue<String> q = new LinkedBlockingQueue<>();
    private final ExecutorService worker = Executors.newSingleThreadExecutor();
    private volatile boolean running = true; private int batchesFlushed = 0;
    AsyncBatchLogger() {
        worker.submit(() -> {
            java.util.List<String> batch = new java.util.ArrayList<>();
            while (running || !q.isEmpty()) {
                String item = q.poll();
                if (item != null) batch.add(item);
                if (batch.size() >= 50) { batchesFlushed++; batch.clear(); }
            }
        });
    }
    void log(String msg) { q.offer(msg); } // instant enqueue, request never waits
    int getBatchesFlushed() { return batchesFlushed; }
    void shutdown() { running = false; worker.shutdown(); }
}

// ─── Would be in perf/RequestCoalescer.java ───
class RequestCoalescer {
    private int downstreamCalls = 0; private int coalesced = 0;
    private final ConcurrentHashMap<String, CompletableFuture<String>> inFlight = new ConcurrentHashMap<>();
    // single-flight: identical concurrent requests share ONE downstream call.
    String lookup(String key, java.util.function.Function<String,String> downstream) {
        CompletableFuture<String> existing = inFlight.get(key);
        if (existing != null) { coalesced++; return existing.join(); }   // join the in-flight call
        CompletableFuture<String> f = new CompletableFuture<>();
        if (inFlight.putIfAbsent(key, f) != null) { coalesced++; return inFlight.get(key).join(); }
        try { downstreamCalls++; String result = downstream.apply(key); f.complete(result); return result; }
        finally { inFlight.remove(key); }
    }
    int getDownstreamCalls() { return downstreamCalls; }
    int getCoalesced() { return coalesced; }
}

// ─── Would be in core/OptimizedGateway.java ───
class OptimizedGateway {
    private static final Logger log = Logger.getLogger("Overhead");
    private final ConnectionPool pool = new ConnectionPool(50);
    private final HybridRateLimiter limiter = new HybridRateLimiter(1000, 100);
    private final AsyncBatchLogger logger = new AsyncBatchLogger();
    private final RequestCoalescer coalescer = new RequestCoalescer();

    void handle(String accountId) {
        if (!limiter.allow()) return;      // local bucket, no Redis per request
        pool.acquire();                    // reuse upstream connection
        logger.log("served " + accountId); // async, off hot path
    }

    String coalescedLookup(String accountId) {
        return coalescer.lookup(accountId, key -> {
            slowDownstream();              // simulate one real backend call
            return key + "=Rs.1000000";
        });
    }

    private void slowDownstream() { try { Thread.sleep(30); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }

    void report() {
        logger.shutdown();
        log.info(() -> String.format("Connection reuse = %.1f%% (new handshakes=%d)",
                pool.reusePercent(), pool.getNewHandshakes()));
        log.info(() -> "Redis syncs=" + limiter.getRedisSyncs() + " (vs per-request Redis calls avoided)");
        log.info(() -> "Coalescing: downstreamCalls=" + coalescer.getDownstreamCalls()
                + " coalesced=" + coalescer.getCoalesced() + " (50 identical → few real calls)");
    }
}

