// ─── presign/PresignService.java ───
// Mints short-lived, scoped presigned URLs. Real impl uses software.amazon.awssdk S3Presigner.
class PresignService {
    final String bucket; final long ttl;
    PresignService(String bucket, long ttlSeconds) { this.bucket = bucket; this.ttl = ttlSeconds; }
    Presigned presignPut(String userId, String filename) {
        String key = userId + "/" + filename;
        String url = "https://" + bucket + ".s3.amazonaws.com/" + key
                + "?X-Amz-Expires=" + ttl + "&X-Amz-Signature=SIM";
        return new Presigned(key, url, Instant.now().plusSeconds(ttl));
    }
    Presigned presignPart(String key, String uploadId, int partNumber) {
        String url = "https://" + bucket + ".s3.amazonaws.com/" + key
                + "?partNumber=" + partNumber + "&uploadId=" + uploadId + "&X-Amz-Signature=SIM";
        return new Presigned(key, url, Instant.now().plusSeconds(ttl));
    }
}
class Presigned { final String key, url; final Instant expiresAt;
    Presigned(String key, String url, Instant exp) { this.key = key; this.url = url; this.expiresAt = exp; } }

// ─── multipart/PartInfo.java ───
class PartInfo { final int number; final String etag;
    PartInfo(int number, String etag) { this.number = number; this.etag = etag; } }

// ─── multipart/MultipartCoordinator.java ───
// Initiates, tracks parts, and completes an S3 multipart upload.
class MultipartCoordinator {
    private static final Logger log = Logger.getLogger(MultipartCoordinator.class.getName());
    private final PresignService presign; private final long partSize;
    private final Map<String, List<PartInfo>> uploads = new HashMap<>();
    MultipartCoordinator(PresignService presign, long partSize) { this.presign = presign; this.partSize = partSize; }

    String initiate(String userId, String filename) {
        String uploadId = "UP-" + UUID.randomUUID();
        uploads.put(uploadId, new ArrayList<>());
        return uploadId;
    }
    int planParts(long totalBytes) { return (int) Math.ceil((double) totalBytes / partSize); }

    void simulateUploadParts(String userId, String filename, String uploadId, int parts) {
        String key = userId + "/" + filename;
        for (int p = 1; p <= parts; p++) {
            Presigned partUrl = presign.presignPart(key, uploadId, p);     // one URL per part
            // client uploads this part directly to S3, receives an ETag
            String etag = "etag-" + p;
            uploads.get(uploadId).add(new PartInfo(p, etag));
            if (p == 1 || p == parts) log.fine("uploaded part " + p + "/" + parts + " via " + partUrl.url);
        }
    }
    void complete(String uploadId) {
        List<PartInfo> parts = uploads.get(uploadId);
        log.info("COMPLETE multipart " + uploadId + " with " + parts.size() + " parts → S3 assembles object");
    }
}

// ─── validate/SizeGuard.java ───
class SizeGuard {
    private final long maxSingle, maxTotal;
    SizeGuard(long maxSingle, long maxTotal) { this.maxSingle = maxSingle; this.maxTotal = maxTotal; }
    void checkSingle(long bytes) {
        if (bytes > maxSingle) throw new FileTooLargeException("use multipart above " + maxSingle + " bytes");
    }
    void checkTotal(long bytes) {
        if (bytes > maxTotal) throw new FileTooLargeException("exceeds absolute cap " + maxTotal + " bytes");
    }
}

// ─── validate/MagicByteValidator.java ───
// Verifies the REAL file type from leading bytes, ignoring extension and declared type.
class MagicByteValidator {
    private final Set<String> allowed;
    MagicByteValidator(Set<String> allowed) { this.allowed = allowed; }
    void validate(String filename, String declaredType, byte[] head) {
        String actual = detect(head);
        if (actual == null || !allowed.contains(actual))
            throw new UnsupportedFileTypeException(
                    "declared=" + declaredType + " but magic bytes say=" + actual + " for " + filename);
    }
    private String detect(byte[] b) {
        if (startsWith(b, '%', 'P', 'D', 'F')) return "application/pdf";
        if (b.length >= 3 && (b[0] & 0xFF) == 0xFF && (b[1] & 0xFF) == 0xD8) return "image/jpeg";
        if (b.length >= 8 && (b[0] & 0xFF) == 0x89 && b[1] == 'P' && b[2] == 'N' && b[3] == 'G') return "image/png";
        if (startsWith(b, 'M', 'Z')) return "application/x-dosexec";   // executable — never allowed
        return null;
    }
    private boolean startsWith(byte[] b, char... sig) {
        if (b.length < sig.length) return false;
        for (int i = 0; i < sig.length; i++) if (b[i] != (byte) sig[i]) return false;
        return true;
    }
}

